VALUES ('doc-09-mitre-attack-p0-10474', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-24T23:51:51.525Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Blue Mockingbird](https://attack.mitre.org/groups/G0108) has used wmic.exe and Windows Registry modifications to set the COR_PROFILER environment variable to execute a malicious DLL whenever a process loads the .NET CLR.(Citation: RedCanary Mockingbird May 2020)", "external_references": [{"description": "Lambert, T. (2020, May 7). Introducing Blue Mockingbird. Retrieved May 26, 2020.", "source_name": "RedCanary Mockingbird May 2020", "url": "https://redcanary.com/blog/blue-mockingbird-cryptominer/"}], "id": "relationship--0e7ce20c-1a4f-4361-a954-1d7a164baca1", "modified": "2026-07-31T18:48:02.633Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--73a80fab-2aa3-48e0-a4d0-3a4828200aee", "spec_version": "2.1", "target_ref": "attack-pattern--ffeb0780-356e-4261-b036-cfb6bd234335", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10474', 0, 81, '09-mitre-attack', 'retrieved', '6F72A16429F1401CF07BFBA8F31FB61B47E2FA9CCD4A45D7B57F49821A705602', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
