VALUES ('doc-09-mitre-attack-p0-10600', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-25T16:48:05.766Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Turla](https://attack.mitre.org/groups/G0010) has used IronPython scripts as part of the [IronNetInjector](https://attack.mitre.org/software/S0581) toolchain to drop payloads.(Citation: Unit 42 IronNetInjector February 2021 )", "external_references": [{"description": "Reichel, D. (2021, February 19). IronNetInjector: Turla’s New Malware Loading Tool. Retrieved February 24, 2021.", "source_name": "Unit 42 IronNetInjector February 2021 ", "url": "https://unit42.paloaltonetworks.com/ironnetinjector/"}], "id": "relationship--afea3455-9565-4e5d-b431-e845ec1722d2", "modified": "2026-07-31T18:48:04.228Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7a19ecb1-3c65-4de3-a230-993516aed6a6", "spec_version": "2.1", "target_ref": "attack-pattern--cc3502b5-30cc-4473-ad48-42d51a6ef6d1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10600', 0, 75, '09-mitre-attack', 'retrieved', '7CD87446EBCBDCD011771E8A1BD14203AE9F6C99523997FD67DEFBCFC2D75B05', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
