VALUES ('doc-09-mitre-attack-p0-10602', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-30T22:12:28.108Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Turla](https://attack.mitre.org/groups/G0010) has used a custom .NET tool to collect documents from an organization''s internal central database.(Citation: ESET ComRAT May 2020)", "external_references": [{"description": "Faou, M. (2020, May). From Agent.btz to ComRAT v4: A ten-year journey. Retrieved June 15, 2020.", "source_name": "ESET ComRAT May 2020", "url": "https://www.welivesecurity.com/wp-content/uploads/2020/05/ESET_Turla_ComRAT.pdf"}], "id": "relationship--b3e2abaa-f431-4791-95d0-d44f3a74a73f", "modified": "2026-07-31T18:48:04.244Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7a19ecb1-3c65-4de3-a230-993516aed6a6", "spec_version": "2.1", "target_ref": "attack-pattern--248d3fe1-7fe1-4d71-91c7-8bb7ef35cad3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10602', 0, 74, '09-mitre-attack', 'retrieved', 'F66C8EFEF9C7BFBEA5B036BC2F9F86595FF97CB1E03CCA9E8CA282C63A99BD09', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
