VALUES ('doc-09-mitre-attack-p0-10626', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-09T20:58:06.163Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Turla](https://attack.mitre.org/groups/G0010) has abused local accounts that have the same password across the victim’s network.(Citation: ESET Crutch December 2020)", "external_references": [{"description": "Faou, M. (2020, December 2). Turla Crutch: Keeping the “back door” open. Retrieved December 4, 2020.", "source_name": "ESET Crutch December 2020", "url": "https://www.welivesecurity.com/2020/12/02/turla-crutch-keeping-back-door-open/"}], "id": "relationship--f4268a0d-0539-46de-bad8-ea72af455585", "modified": "2026-07-31T18:48:04.428Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7a19ecb1-3c65-4de3-a230-993516aed6a6", "spec_version": "2.1", "target_ref": "attack-pattern--fdc47f44-dd32-4b99-af5f-209f556f63c2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10626', 0, 72, '09-mitre-attack', 'retrieved', '507662AD210D358B7F16FB80F4EDBF19FF493623289D5665821DB0AAC9A318E9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
