VALUES ('doc-09-mitre-attack-p0-10633', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T19:35:36.466Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-0501](https://attack.mitre.org/groups/G1053) has used legitimate remote monitoring and management (RMM) tools including AnyDesk, NinjaOne, and Level.io.(Citation: Microsoft Storm-501 Sabbath Ransomware Embargo September 2024)", "external_references": [{"description": "Microsoft Threat Intelligence. (2024, September 26). Storm-0501: Ransomware attacks expanding to hybrid cloud environments. Retrieved October 19, 2025.", "source_name": "Microsoft Storm-501 Sabbath Ransomware Embargo September 2024", "url": "https://www.microsoft.com/en-us/security/blog/2024/09/26/storm-0501-ransomware-attacks-expanding-to-hybrid-cloud-environments/"}], "id": "relationship--0ea2fee2-66aa-4c6a-9617-94cbdbdf4d4b", "modified": "2026-07-31T18:48:03.515Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7b404cd0-3ae9-41d4-90c0-023793d35d97", "spec_version": "2.1", "target_ref": "attack-pattern--d4287702-e2f7-4946-bdfa-2c7f5aaa5032", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10633', 0, 81, '09-mitre-attack', 'retrieved', '90772FC9E76C41B199AC102EEA2FEDB4A0FB0E5A5856C7A4948A8949A34CF1C5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
