VALUES ('doc-09-mitre-attack-p0-10653', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T19:52:42.841Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-0501](https://attack.mitre.org/groups/G1053) has engaged in double-extortion ransomware, exfiltrating data and directly contacting victims when the primary organization refuses to pay along with posting data on their data leak sites.(Citation: Avertium Storm-0501 Sabbath Ransomware Arcane January 2022)(Citation: Microsoft Storm-0501 Embargo Ransomware August 2025)(Citation: Google Mandiant Storm-0501 Sabbath Ransomware November 2021)", "external_references": [{"description": "Avertium. (2022, January 11). An In-Depth Look at Ransomware Gang, Sabbath. Retrieved October 19, 2025.", "source_name": "Avertium Storm-0501 Sabbath Ransomware Arcane January 2022", "url": "https://www.avertium.com/resources/threat-reports/in-depth-look-at-sabbath-ransomware-gang"}, {"description": "Microsoft Threat Intelligence. (2025, August 27). Storm-0501’s evolving techniques lead to cloud-based ransomware. Retrieved October 19, 2025.", "source_name": "Microsoft Storm-0501 Embargo Ransomware August 2025", "url": "https://www.microsoft.com/en-us/security/blog/2025/08/27/storm-0501s-evolving-techniques-lead-to-cloud-based-ransomware/"}, {"description": "Tyler McLellan, Brandan Schondorfer. (2021, November 29). Kitten.gif: Meet the Sabbath Ransomware Affiliate Program, Again. Retrieved October 19, 2025.", "source_name": "Google Mandiant Storm-0501 Sabbath Ransomware November 2021", "url": "https://cloud.google.com/blog/topics/threat-intelligence/sabbath-ransomware-affiliate/"}], "id": "relationship--73f90bbd-538b-49d8-a84c-86b0353a5557", "modified": "2026-07-31T18:48:03.769Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7b404cd0-3ae9-41d4-90c0-023793d35d97", "spec