VALUES ('doc-09-mitre-attack-p0-10654', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T19:14:46.328Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-0501](https://attack.mitre.org/groups/G1053) has utilized [Rclone](https://attack.mitre.org/software/S1040) for data exfiltration.(Citation: Microsoft Storm-501 Sabbath Ransomware Embargo September 2024)", "external_references": [{"description": "Microsoft Threat Intelligence. (2024, September 26). Storm-0501: Ransomware attacks expanding to hybrid cloud environments. Retrieved October 19, 2025.", "source_name": "Microsoft Storm-501 Sabbath Ransomware Embargo September 2024", "url": "https://www.microsoft.com/en-us/security/blog/2024/09/26/storm-0501-ransomware-attacks-expanding-to-hybrid-cloud-environments/"}], "id": "relationship--7b82c1d0-b675-47bd-bb8c-3e0fb96c304a", "modified": "2026-07-31T18:48:03.785Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7b404cd0-3ae9-41d4-90c0-023793d35d97", "spec_version": "2.1", "target_ref": "tool--59096109-a1dd-463b-87e7-a8d110fe3a79", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10654', 0, 73, '09-mitre-attack', 'retrieved', '41A0919BC6BCB8D61A35549938543C5A34D0B968B4218B433A7B1CF17D527C42', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
