VALUES ('doc-09-mitre-attack-p0-10664', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T19:36:52.674Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-0501](https://attack.mitre.org/groups/G1053) has leveraged native Windows tools and commands such as `systeminfo` and open-source tools including OSQuery and ossec-win32 to query details about the endpoint.(Citation: Microsoft Storm-501 Sabbath Ransomware Embargo September 2024)", "external_references": [{"description": "Microsoft Threat Intelligence. (2024, September 26). Storm-0501: Ransomware attacks expanding to hybrid cloud environments. Retrieved October 19, 2025.", "source_name": "Microsoft Storm-501 Sabbath Ransomware Embargo September 2024", "url": "https://www.microsoft.com/en-us/security/blog/2024/09/26/storm-0501-ransomware-attacks-expanding-to-hybrid-cloud-environments/"}], "id": "relationship--baf93cec-ad47-4380-bda7-9569e088b5e9", "modified": "2026-07-31T18:48:03.915Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7b404cd0-3ae9-41d4-90c0-023793d35d97", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10664', 0, 90, '09-mitre-attack', 'retrieved', 'EA67A79CA3ED492E8C5796E723897AAAE2DF28F295E4D48F251563BCC0907DF9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
