VALUES ('doc-09-mitre-attack-p0-10665', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T19:54:56.283Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-0501](https://attack.mitre.org/groups/G1053) has used Themida to pack [Cobalt Strike](https://attack.mitre.org/software/S0154) payloads.(Citation: Google Mandiant Storm-0501 Sabbath Ransomware November 2021)", "external_references": [{"description": "Tyler McLellan, Brandan Schondorfer. (2021, November 29). Kitten.gif: Meet the Sabbath Ransomware Affiliate Program, Again. Retrieved October 19, 2025.", "source_name": "Google Mandiant Storm-0501 Sabbath Ransomware November 2021", "url": "https://cloud.google.com/blog/topics/threat-intelligence/sabbath-ransomware-affiliate/"}], "id": "relationship--bf20f37d-ce08-44f1-bc68-f444aabde3c7", "modified": "2026-07-31T18:48:03.928Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7b404cd0-3ae9-41d4-90c0-023793d35d97", "spec_version": "2.1", "target_ref": "attack-pattern--deb98323-e13f-4b0c-8d94-175379069062", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10665', 0, 76, '09-mitre-attack', 'retrieved', 'A3D8662BC8FDC9DC4E3FED6BA2C66A00D04439C38B5BFEE56765B6760C0C29ED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
