VALUES ('doc-09-mitre-attack-p0-10667', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T20:06:44.609Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-0501](https://attack.mitre.org/groups/G1053) has leveraged the Azure Owner role to access and steal the Storage Account Access keys using the `Microsoft.Storage/storageAccounts/listkeys/action` operation.(Citation: Microsoft Storm-0501 Embargo Ransomware August 2025)", "external_references": [{"description": "Microsoft Threat Intelligence. (2025, August 27). Storm-0501’s evolving techniques lead to cloud-based ransomware. Retrieved October 19, 2025.", "source_name": "Microsoft Storm-0501 Embargo Ransomware August 2025", "url": "https://www.microsoft.com/en-us/security/blog/2025/08/27/storm-0501s-evolving-techniques-lead-to-cloud-based-ransomware/"}], "id": "relationship--dabf635b-40fd-45e1-b7b8-ed6de9d1bf22", "modified": "2026-07-31T18:48:03.950Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7b404cd0-3ae9-41d4-90c0-023793d35d97", "spec_version": "2.1", "target_ref": "attack-pattern--60b508a1-6a5e-46b1-821a-9f7b78752abf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10667', 0, 83, '09-mitre-attack', 'retrieved', '1FB9C4E340B2F6369585A786D2F3ACD515FB8D260296A6CCB025BE02DD4FAB0D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
