VALUES ('doc-09-mitre-attack-p0-10672', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T19:55:31.013Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-0501](https://attack.mitre.org/groups/G1053) has utilized their own self-signed TLS certificate “Microsoft IT TLS CA 5” with their infrastructure.(Citation: Google Mandiant Storm-0501 Sabbath Ransomware November 2021)", "external_references": [{"description": "Tyler McLellan, Brandan Schondorfer. (2021, November 29). Kitten.gif: Meet the Sabbath Ransomware Affiliate Program, Again. Retrieved October 19, 2025.", "source_name": "Google Mandiant Storm-0501 Sabbath Ransomware November 2021", "url": "https://cloud.google.com/blog/topics/threat-intelligence/sabbath-ransomware-affiliate/"}], "id": "relationship--e612293a-23f1-457e-b92c-43c84f57389a", "modified": "2026-07-31T18:48:04.009Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7b404cd0-3ae9-41d4-90c0-023793d35d97", "spec_version": "2.1", "target_ref": "attack-pattern--1cec9319-743b-4840-bb65-431547bce82a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10672', 0, 83, '09-mitre-attack', 'retrieved', '135A8D2A93E609D73B3A5DDB6617DCF035F5A26882A5F752A0517565B4ADA2BF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
