VALUES ('doc-09-mitre-attack-p0-10674', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T19:17:37.980Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-0501](https://attack.mitre.org/groups/G1053) has used the [Net](https://attack.mitre.org/software/S0039) utility on the Windows operating system.(Citation: Microsoft Storm-501 Sabbath Ransomware Embargo September 2024)(Citation: Microsoft Storm-0501 Embargo Ransomware August 2025)", "external_references": [{"description": "Microsoft Threat Intelligence. (2024, September 26). Storm-0501: Ransomware attacks expanding to hybrid cloud environments. Retrieved October 19, 2025.", "source_name": "Microsoft Storm-501 Sabbath Ransomware Embargo September 2024", "url": "https://www.microsoft.com/en-us/security/blog/2024/09/26/storm-0501-ransomware-attacks-expanding-to-hybrid-cloud-environments/"}, {"description": "Microsoft Threat Intelligence. (2025, August 27). Storm-0501’s evolving techniques lead to cloud-based ransomware. Retrieved October 19, 2025.", "source_name": "Microsoft Storm-0501 Embargo Ransomware August 2025", "url": "https://www.microsoft.com/en-us/security/blog/2025/08/27/storm-0501s-evolving-techniques-lead-to-cloud-based-ransomware/"}], "id": "relationship--eea7a647-322f-4d4a-a6b4-28b3b8ca8f32", "modified": "2026-07-31T18:48:04.031Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7b404cd0-3ae9-41d4-90c0-023793d35d97", "spec_version": "2.1", "target_ref": "tool--03342581-f790-4f03-ba41-e82e67392e23", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10674', 0, 110, '09-mitre-attack', 'retrieved', '8681F879A704B4906D6ABA0C506ABF60A6F1D7DEF54D436E00C9A184B4E8C3A0', 'v1', '{"source_id": "0