VALUES ('doc-09-mitre-attack-p0-10677', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T20:02:27.180Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-0501](https://attack.mitre.org/groups/G1053) has reset the password of identified administrator accounts that lack MFA and registered their own MFA method.(Citation: Microsoft Storm-0501 Embargo Ransomware August 2025)", "external_references": [{"description": "Microsoft Threat Intelligence. (2025, August 27). Storm-0501’s evolving techniques lead to cloud-based ransomware. Retrieved October 19, 2025.", "source_name": "Microsoft Storm-0501 Embargo Ransomware August 2025", "url": "https://www.microsoft.com/en-us/security/blog/2025/08/27/storm-0501s-evolving-techniques-lead-to-cloud-based-ransomware/"}], "id": "relationship--fbae351b-0a1a-4761-9e5f-31aa39eb98d1", "modified": "2026-07-31T18:48:04.078Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7b404cd0-3ae9-41d4-90c0-023793d35d97", "spec_version": "2.1", "target_ref": "attack-pattern--8a2f40cf-8325-47f9-96e4-b1ca4c7389bd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10677', 0, 81, '09-mitre-attack', 'retrieved', '6448D44FBE4589ED50FCF4884DF089F28E373B0246FEB91F0303B5A7B88DE514', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
