VALUES ('doc-09-mitre-attack-p0-10697', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-07-14T17:21:28.886Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TA505](https://attack.mitre.org/groups/G0092) has used malware to disable Windows Defender through modification of the Registry.(Citation: Korean FSI TA505 2020)", "external_references": [{"description": "Financial Security Institute. (2020, February 28). Profiling of TA505 Threat Group That Continues to Attack the Financial Sector. Retrieved July 14, 2022.", "source_name": "Korean FSI TA505 2020", "url": "https://www.fsec.or.kr/user/bbs/fsec/163/344/bbsDataView/1382.do?page=1&column=&search=&searchSDate=&searchEDate=&bbsDataCategory="}], "id": "relationship--3debe0d7-63bb-4e21-bf9b-ed5e23140e57", "modified": "2026-07-31T18:48:05.392Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7eda3dd8-b09b-4705-8090-c2ad9fb8c14d", "spec_version": "2.1", "target_ref": "attack-pattern--57340c81-c025-4189-8fa0-fc7ede51bae4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10697', 0, 77, '09-mitre-attack', 'retrieved', 'E9A89A3CCB120AE26D990673E0C9570069F40182631453A6581BDEEF6EC4FC63', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
