VALUES ('doc-09-mitre-attack-p0-10698', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-13T16:06:06.012Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TA505](https://attack.mitre.org/groups/G0092) has used a variety of tools in their operations, including [AdFind](https://attack.mitre.org/software/S0552), [BloodHound](https://attack.mitre.org/software/S0521), [Mimikatz](https://attack.mitre.org/software/S0002), and [PowerSploit](https://attack.mitre.org/software/S0194).(Citation: NCC Group TA505)", "external_references": [{"description": "Terefos, A. (2020, November 18). TA505: A Brief History of Their Time. Retrieved July 14, 2022.", "source_name": "NCC Group TA505", "url": "https://research.nccgroup.com/2020/11/18/ta505-a-brief-history-of-their-time/"}], "id": "relationship--3e6b6ed9-4c28-4dd0-903a-360f57864de4", "modified": "2026-07-31T18:48:05.405Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--7eda3dd8-b09b-4705-8090-c2ad9fb8c14d", "spec_version": "2.1", "target_ref": "attack-pattern--a2fdce72-04b2-409a-ac10-cc1695f4fce0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10698', 0, 72, '09-mitre-attack', 'retrieved', 'F4803F317E71B3C839949A6BD2ECBB72875AAC3B88E565AB9C25396857682370', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
