VALUES ('doc-09-mitre-attack-p0-10764', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-15T13:43:22.758Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkVishnya](https://attack.mitre.org/groups/G0105) used ports 5190 and 7900 for shellcode listeners, and 4444, 4445, 31337 for shellcode C2.(Citation: Securelist DarkVishnya Dec 2018)", "external_references": [{"description": "Golovanov, S. (2018, December 6). DarkVishnya: Banks attacked through direct connection to local network. Retrieved May 15, 2020.", "source_name": "Securelist DarkVishnya Dec 2018", "url": "https://securelist.com/darkvishnya/89169/"}], "id": "relationship--ca38f31f-3551-49e3-835b-588693a8b512", "modified": "2026-07-31T18:48:05.296Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--813636db-3939-4a45-bea9-6113e970c029", "spec_version": "2.1", "target_ref": "attack-pattern--b18eae87-b469-4e14-b454-b171b416bc18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10764', 0, 76, '09-mitre-attack', 'retrieved', 'BBF657CD168C5D0C634AC31BF66093B2E51A08FD367B4F67EEDD6E8459EBF802', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
