VALUES ('doc-09-mitre-attack-p0-10765', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-23T22:28:57.568Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedCurl](https://attack.mitre.org/groups/G1039) has used malware with string encryption.(Citation: therecord_redcurl) [RedCurl](https://attack.mitre.org/groups/G1039) has also encrypted data and has encoded PowerShell commands using Base64.(Citation: group-ib_redcurl1)(Citation: group-ib_redcurl2) [RedCurl](https://attack.mitre.org/groups/G1039) has used `PyArmor` to obfuscate code execution of [LaZagne](https://attack.mitre.org/software/S0349). (Citation: group-ib_redcurl1) Additionally, [RedCurl](https://attack.mitre.org/groups/G1039) has obfuscated downloaded files by renaming them as commonly used tools and has used `echo`, instead of file names themselves, to execute files.(Citation: trendmicro_redcurl) \n", "external_references": [{"description": "Antoniuk, D. (2023, July 17). RedCurl hackers return to spy on ''major Russian bank,'' Australian company. Retrieved August 9, 2024.", "source_name": "therecord_redcurl", "url": "https://therecord.media/redcurl-hackers-russian-bank-australian-company"}, {"description": "Group-IB. (2020, August). RedCurl: The Pentest You Didn’t Know About. Retrieved August 9, 2024.", "source_name": "group-ib_redcurl1", "url": "https://www.group-ib.com/resources/research-hub/red-curl/"}, {"description": "Group-IB. (2021, November). RedCurl: The Awakening. Retrieved August 14, 2024.", "source_name": "group-ib_redcurl2", "url": "https://www.group-ib.com/resources/research-hub/red-curl-2/"}, {"description": "Tancio et al. (2024, March 6). Unveiling Earth Kapre aka RedCurl’s Cyberespionage Tactics With Trend Micro MDR, Threat Intelligence. Retrieved August 9, 2024.", "source_name": "trendmicro_redcurl", "url": "https://www.trendmicro.com/en_us/research/24/c/unveiling-earth-kapre-aka-redcurls-cyberespionage-tactics-with-t.html"}], "id": "relationship--06fbdb2f-97d5-4140-9300-0a1f6ab72cb2", "modified": "2026-07-31T18:48:05.888Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--82323c70-4186-4b61-94f5-b227c3b28e89", "spec_version": "2.1", "target_ref": "attack-pattern--b3d682b6-98f2-4fb0-aa3b-b4df007ca70a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10765', 0, 178, '09-mitre-attack', 'retrieved', '6C09A1763255F49C104FD7F5E6D66A0C4003C55934FC794E5293EA66B2030674', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
