VALUES ('doc-09-mitre-attack-p0-10802', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-23T22:15:39.651Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedCurl](https://attack.mitre.org/groups/G1039) has used a Python script to establish outbound communication and to execute commands using SMB port 445.(Citation: trendmicro_redcurl) ", "external_references": [{"description": "Tancio et al. (2024, March 6). Unveiling Earth Kapre aka RedCurl’s Cyberespionage Tactics With Trend Micro MDR, Threat Intelligence. Retrieved August 9, 2024.", "source_name": "trendmicro_redcurl", "url": "https://www.trendmicro.com/en_us/research/24/c/unveiling-earth-kapre-aka-redcurls-cyberespionage-tactics-with-t.html"}], "id": "relationship--e5cf97c0-5229-4d94-bd23-9dfa1517d8b3", "modified": "2026-07-31T18:48:06.493Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--82323c70-4186-4b61-94f5-b227c3b28e89", "spec_version": "2.1", "target_ref": "attack-pattern--cc3502b5-30cc-4473-ad48-42d51a6ef6d1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10802', 0, 78, '09-mitre-attack', 'retrieved', '0FF82586D1C72DD8814F1B1981EF9EC9414EA0C3DC1A2F23A0572BFBE63CA6AF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
