VALUES ('doc-09-mitre-attack-p0-10816', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-12T22:04:56.899Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN5](https://attack.mitre.org/groups/G0053) has obtained and used a customized version of [PsExec](https://attack.mitre.org/software/S0029), as well as use other tools such as [pwdump](https://attack.mitre.org/software/S0006), [SDelete](https://attack.mitre.org/software/S0195), and [Windows Credential Editor](https://attack.mitre.org/software/S0005).(Citation: Mandiant FIN5 GrrCON Oct 2016)", "external_references": [{"description": "Bromiley, M. and Lewis, P. (2016, October 7). Attacking the Hospitality and Gaming Industries: Tracking an Attacker Around the World in 7 Years. Retrieved October 6, 2017.", "source_name": "Mandiant FIN5 GrrCON Oct 2016", "url": "https://www.youtube.com/watch?v=fevGZs0EQu8"}], "id": "relationship--7c240038-5599-418a-83e4-6d9962eee0bd", "modified": "2026-07-31T20:48:40.291Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--85403903-15e0-4f9f-9be4-a259ecad4022", "spec_version": "2.1", "target_ref": "attack-pattern--a2fdce72-04b2-409a-ac10-cc1695f4fce0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10816', 0, 95, '09-mitre-attack', 'retrieved', '8F9DA5BF98BF0E1567088BD9E2A697DBBF8B6D59786219F1BF38AD6AB0260A50', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
