VALUES ('doc-09-mitre-attack-p0-10902', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-28T19:05:12.518Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT29](https://attack.mitre.org/groups/G0016) has enrolled their own devices into compromised cloud tenants, including enrolling a device in MFA to an Azure AD environment following a successful password guessing attack against a dormant account.(Citation: Mandiant APT29 Microsoft 365 2022)(Citation: NCSC et al APT29 2024)", "external_references": [{"description": "Douglas Bienstock. (2022, August 18). You Can’t Audit Me: APT29 Continues Targeting Microsoft 365. Retrieved February 23, 2023.", "source_name": "Mandiant APT29 Microsoft 365 2022", "url": "https://www.mandiant.com/resources/blog/apt29-continues-targeting-microsoft"}, {"description": "UK National Cyber Security Center et al. (2024, February). SVR cyber actors adapt tactics for initial cloud access. Retrieved March 1, 2024.", "source_name": "NCSC et al APT29 2024", "url": "https://www.ic3.gov/Media/News/2024/240226.pdf"}], "id": "relationship--3bd11b5b-4dba-4612-98e0-0f3e18686123", "modified": "2026-07-31T18:48:07.739Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--899ce53f-13a0-479b-a0e4-67d46e241542", "spec_version": "2.1", "target_ref": "attack-pattern--7decb26c-715c-40cf-b7e0-026f7d7cc215", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10902', 0, 129, '09-mitre-attack', 'retrieved', 'BAE5634C58247C44ED7FB859FDEDB1B07905895494A760B037AE8CA86B9A1691', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
