VALUES ('doc-09-mitre-attack-p0-10916', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-12T16:17:34.877Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT29](https://attack.mitre.org/groups/G0016) has registered algorithmically generated Twitter handles that are used for C2 by malware, such as [HAMMERTOSS](https://attack.mitre.org/software/S0037). [APT29](https://attack.mitre.org/groups/G0016) has also used legitimate web services such as Dropbox and Constant Contact in their operations.(Citation: FireEye APT29)(Citation: MSTIC NOBELIUM May 2021)", "external_references": [{"description": "FireEye Labs. (2015, July). HAMMERTOSS: Stealthy Tactics Define a Russian Cyber Threat Group. Retrieved November 17, 2024.", "source_name": "FireEye APT29", "url": "https://services.google.com/fh/files/misc/rpt-apt29-hammertoss-stealthy-tactics-define-en.pdf"}, {"description": "Microsoft Threat Intelligence Center (MSTIC). (2021, May 27). New sophisticated email-based attack from NOBELIUM. Retrieved May 28, 2021.", "source_name": "MSTIC NOBELIUM May 2021", "url": "https://www.microsoft.com/security/blog/2021/05/27/new-sophisticated-email-based-attack-from-nobelium/"}], "id": "relationship--53a6a12f-04f2-445b-b733-8392ade1a7e5", "modified": "2026-07-31T18:48:07.960Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--899ce53f-13a0-479b-a0e4-67d46e241542", "spec_version": "2.1", "target_ref": "attack-pattern--88d31120-5bc7-4ce3-a9c0-7cf147be8e54", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10916', 0, 118, '09-mitre-attack', 'retrieved', 'AA7B31F81735904BE4E877594BBD0B5F63028E80A76C583694FE89A6C1953449', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
