VALUES ('doc-09-mitre-attack-p0-10925', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-16T21:33:50.834Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT29](https://attack.mitre.org/groups/G0016) has renamed malicious DLLs with legitimate names to appear benign; they have also created an Azure AD certificate with a Common Name that matched the display name of the compromised service principal.(Citation: SentinelOne NobleBaron June 2021)(Citation: Mandiant APT29 Microsoft 365 2022)", "external_references": [{"description": "Douglas Bienstock. (2022, August 18). You Can’t Audit Me: APT29 Continues Targeting Microsoft 365. Retrieved February 23, 2023.", "source_name": "Mandiant APT29 Microsoft 365 2022", "url": "https://www.mandiant.com/resources/blog/apt29-continues-targeting-microsoft"}, {"description": "Guerrero-Saade, J. (2021, June 1). NobleBaron | New Poisoned Installers Could Be Used In Supply Chain Attacks. Retrieved August 4, 2021.", "source_name": "SentinelOne NobleBaron June 2021", "url": "https://labs.sentinelone.com/noblebaron-new-poisoned-installers-could-be-used-in-supply-chain-attacks/"}], "id": "relationship--6828b200-b067-4667-9a77-9e434a625eaf", "modified": "2026-07-31T18:48:08.119Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--899ce53f-13a0-479b-a0e4-67d46e241542", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10925', 0, 128, '09-mitre-attack', 'retrieved', 'DB524FC611BBBF862D6EE811C27E9F4F07DA52767AB95F28981F01D0A82ACE4C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type"