VALUES ('doc-09-mitre-attack-p0-10927', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-04T18:30:20.293Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT29](https://attack.mitre.org/groups/G0016) has conducted brute force password spray attacks.(Citation: MSRC Nobelium June 2021)(Citation: MSTIC Nobelium Oct 2021)(Citation: NCSC et al APT29 2024)", "external_references": [{"description": "Microsoft Threat Intelligence Center. (2021, October 25). NOBELIUM targeting delegated administrative privileges to facilitate broader attacks. Retrieved March 25, 2022.", "source_name": "MSTIC Nobelium Oct 2021", "url": "https://www.microsoft.com/security/blog/2021/10/25/nobelium-targeting-delegated-administrative-privileges-to-facilitate-broader-attacks/"}, {"description": "MSRC. (2021, June 25). New Nobelium activity. Retrieved August 4, 2021.", "source_name": "MSRC Nobelium June 2021", "url": "https://msrc-blog.microsoft.com/2021/06/25/new-nobelium-activity/"}, {"description": "UK National Cyber Security Center et al. (2024, February). SVR cyber actors adapt tactics for initial cloud access. Retrieved March 1, 2024.", "source_name": "NCSC et al APT29 2024", "url": "https://www.ic3.gov/Media/News/2024/240226.pdf"}], "id": "relationship--6c4b2975-6cad-4a10-8006-1e2e973a8a8b", "modified": "2026-07-31T18:48:08.166Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--899ce53f-13a0-479b-a0e4-67d46e241542", "spec_version": "2.1", "target_ref": "attack-pattern--692074ae-bb62-4a5e-a735-02cb6bde458c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10927', 0, 129, '09-mitre-attack', 'retrieved', 'D4271330D5E545DDC0D30D67630B02A52DE84605B6BFC692356535377DA605B1', 'v1', '{