VALUES ('doc-09-mitre-attack-p0-10932', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-16T19:04:13.561Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: FireEye SUNBURST Backdoor December 2020)(Citation: MSTIC NOBELIUM May 2021)(Citation: MSTIC Nobelium Toolset May 2021)(Citation: Secureworks IRON RITUAL Profile)", "external_references": [{"description": "FireEye. (2020, December 13). Highly Evasive Attacker Leverages SolarWinds Supply Chain to Compromise Multiple Global Victims With SUNBURST Backdoor. Retrieved January 4, 2021.", "source_name": "FireEye SUNBURST Backdoor December 2020", "url": "https://www.fireeye.com/blog/threat-research/2020/12/evasive-attacker-leverages-solarwinds-supply-chain-compromises-with-sunburst-backdoor.html"}, {"description": "Microsoft Threat Intelligence Center (MSTIC). (2021, May 27). New sophisticated email-based attack from NOBELIUM. Retrieved May 28, 2021.", "source_name": "MSTIC NOBELIUM May 2021", "url": "https://www.microsoft.com/security/blog/2021/05/27/new-sophisticated-email-based-attack-from-nobelium/"}, {"description": "MSTIC. (2021, May 28). Breaking down NOBELIUM’s latest early-stage toolset. Retrieved August 4, 2021.", "source_name": "MSTIC Nobelium Toolset May 2021", "url": "https://www.microsoft.com/security/blog/2021/05/28/breaking-down-nobeliums-latest-early-stage-toolset/"}, {"description": "Secureworks CTU. (n.d.). IRON RITUAL. Retrieved February 24, 2022.", "source_name": "Secureworks IRON RITUAL Profile", "url": "https://www.sophos.com/en-us/threat-profiles/iron-ritual"}], "id": "relationship--79b3c546-efbf-4642-b5f1-61d4b497d4b9", "modified": "2026-07-31T18:48:08.260Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--899ce53f-13a0-479b-a0e4-67d46e241542", "spec_version": "2.1", "target_ref": "malware--32f49626-87f4-4d6c-8f59-a0dca953