VALUES ('doc-09-mitre-attack-p0-10934', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.048Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT29](https://attack.mitre.org/groups/G0016) has used encoded PowerShell scripts uploaded to [CozyCar](https://attack.mitre.org/software/S0046) installations to download and install [SeaDuke](https://attack.mitre.org/software/S0053).(Citation: Symantec Seaduke 2015)(Citation: Mandiant No Easy Breach)(Citation: ESET T3 Threat Report 2021)(Citation: Secureworks IRON HEMLOCK Profile)", "external_references": [{"description": "Dunwoody, M. and Carr, N.. (2016, September 27). No Easy Breach DerbyCon 2016. Retrieved September 12, 2024.", "source_name": "Mandiant No Easy Breach", "url": "https://www.slideshare.net/slideshow/no-easy-breach-derby-con-2016/66447908"}, {"description": "ESET. (2022, February). THREAT REPORT T3 2021. Retrieved February 10, 2022.", "source_name": "ESET T3 Threat Report 2021", "url": "https://www.welivesecurity.com/wp-content/uploads/2022/02/eset_threat_report_t32021.pdf"}, {"description": "Secureworks CTU. (n.d.). IRON HEMLOCK. Retrieved February 22, 2022.", "source_name": "Secureworks IRON HEMLOCK Profile", "url": "http://www.secureworks.com/research/threat-profiles/iron-hemlock"}, {"description": "Symantec Security Response. (2015, July 13). “Forkmeiamfamous”: Seaduke, latest weapon in the Duke armory. Retrieved July 22, 2015.", "source_name": "Symantec Seaduke 2015", "url": "https://web.archive.org/web/20150717011546/http://www.symantec.com/connect/blogs/forkmeiamfamous-seaduke-latest-weapon-duke-armory"}], "id": "relationship--7f78df2e-e6e9-43f1-815b-58e4a10fc594", "modified": "2026-07-31T18:48:08.302Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--899ce53f-13a0-479b-a0e4-67d46e241542", "spec_version": "2.1", "target_ref