VALUES ('doc-09-mitre-attack-p0-10938', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-02-21T19:44:52.974Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT29](https://attack.mitre.org/groups/G0016) has leveraged compromised high-privileged on-premises accounts synced to Office 365 to move laterally into a cloud environment, including through the use of Azure AD PowerShell.(Citation: Mandiant Remediation and Hardening Strategies for Microsoft 365)", "external_references": [{"description": "Mandiant. (2022, August). Remediation and Hardening Strategies for Microsoft 365 to Defend Against APT29. Retrieved February 21, 2023.", "source_name": "Mandiant Remediation and Hardening Strategies for Microsoft 365", "url": "https://www.mandiant.com/sites/default/files/2022-08/remediation-hardening-strategies-for-m365-defend-against-apt29-white-paper.pdf"}], "id": "relationship--93e345d9-a7d2-4abd-be34-46211fa64a7d", "modified": "2026-07-31T18:48:08.364Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--899ce53f-13a0-479b-a0e4-67d46e241542", "spec_version": "2.1", "target_ref": "attack-pattern--8861073d-d1b8-4941-82ce-dce621d398f0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10938', 0, 94, '09-mitre-attack', 'retrieved', '48CD1AD61680AEEAA2BB432F92E84526196C1986832F3C6C0F3E66BFB40BC2E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
