VALUES ('doc-09-mitre-attack-p0-11055', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-27T21:22:39.805Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Chimera](https://attack.mitre.org/groups/G0114) has used PowerShell scripts to execute malicious payloads and the DSInternals PowerShell module to make use of Active Directory features.(Citation: Cycraft Chimera April 2020)(Citation: NCC Group Chimera January 2021)\t", "external_references": [{"description": "Cycraft. (2020, April 15). APT Group Chimera - APT Operation Skeleton key Targets Taiwan Semiconductor Vendors. Retrieved August 24, 2020..", "source_name": "Cycraft Chimera April 2020", "url": "https://web.archive.org/web/20231214094657/https://cycraft.com/download/CyCraft-Whitepaper-Chimera_V4.1.pdf"}, {"description": "Jansen, W . (2021, January 12). Abusing cloud services to fly under the radar. Retrieved September 12, 2024.", "source_name": "NCC Group Chimera January 2021", "url": "https://web.archive.org/web/20230218064220/https://research.nccgroup.com/2021/01/12/abusing-cloud-services-to-fly-under-the-radar/"}], "id": "relationship--6337cf38-4b52-4e3d-a63e-670e077ec52f", "modified": "2026-07-31T20:48:41.322Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--8c1f0187-0826-4320-bddc-5f326cfcfe2c", "spec_version": "2.1", "target_ref": "attack-pattern--970a3432-3237-47ad-bcca-7d8cbb217736", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11055', 0, 115, '09-mitre-attack', 'retrieved', 'B7B8A8DB878D909507435651C477C7B21E1B47AE1DC050FDC3F4AF7F28DDF97D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
