VALUES ('doc-09-mitre-attack-p0-11065', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-22T21:20:21.217Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Chimera](https://attack.mitre.org/groups/G0114) has used [ipconfig](https://attack.mitre.org/software/S0100), [Ping](https://attack.mitre.org/software/S0097), and tracert to enumerate the IP address and network environment and settings of the local host.(Citation: NCC Group Chimera January 2021)", "external_references": [{"description": "Jansen, W . (2021, January 12). Abusing cloud services to fly under the radar. Retrieved September 12, 2024.", "source_name": "NCC Group Chimera January 2021", "url": "https://web.archive.org/web/20230218064220/https://research.nccgroup.com/2021/01/12/abusing-cloud-services-to-fly-under-the-radar/"}], "id": "relationship--817b9a3f-dec4-4269-ab36-4788c6e11c7b", "modified": "2026-07-31T20:48:41.397Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--8c1f0187-0826-4320-bddc-5f326cfcfe2c", "spec_version": "2.1", "target_ref": "attack-pattern--707399d6-ab3e-4963-9315-d9d3818cd6a0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11065', 0, 83, '09-mitre-attack', 'retrieved', '34E4989373220EC50DB3941F8334A4D71E3835CF0C7AA141CAA0F4546F71E686', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
