VALUES ('doc-09-mitre-attack-p0-11165', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-15T00:52:01.922Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cleaver](https://attack.mitre.org/groups/G0003) has created customized tools and payloads for functions including ARP poisoning, encryption, credential dumping, ASP.NET shells, web backdoors, process enumeration, WMI querying, HTTP and SMB communications, network interface sniffing, and keystroke logging.(Citation: Cylance Cleaver)", "external_references": [{"description": "Cylance. (2014, December). Operation Cleaver. Retrieved September 14, 2017.", "source_name": "Cylance Cleaver", "url": "https://web.archive.org/web/20200302085133/https://www.cylance.com/content/dam/cylance/pages/operation-cleaver/Cylance_Operation_Cleaver_Report.pdf"}], "id": "relationship--7dbfb31d-8ac7-44c5-ad9b-f22e07e95d7e", "modified": "2026-07-31T18:48:08.620Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--8f5e8dc7-739d-4f5e-a8a1-a66e004d7063", "spec_version": "2.1", "target_ref": "attack-pattern--212306d8-efa4-44c9-8c2d-ed3d2e224aa0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11165', 0, 80, '09-mitre-attack', 'retrieved', '33063F1175CEA6E386E2FFC6940443781D21682EAAA54094F12A71C3F08AB299', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
