VALUES ('doc-09-mitre-attack-p0-11169', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-03T16:59:34.743Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Silent Librarian](https://attack.mitre.org/groups/G0122) has searched victim''s websites to identify the interests and academic areas of targeted individuals and to scrape source code, branding, and organizational contact information for phishing pages.(Citation: DOJ Iran Indictments March 2018)(Citation: Phish Labs Silent Librarian)(Citation: Proofpoint TA407 September 2019)", "external_references": [{"description": "DOJ. (2018, March 23). U.S. v. Rafatnejad et al . Retrieved February 3, 2021.", "source_name": "DOJ Iran Indictments March 2018", "url": "https://www.justice.gov/usao-sdny/press-release/file/1045781/download"}, {"description": "Hassold, Crane. (2018, March 26). Silent Librarian: More to the Story of the Iranian Mabna Institute Indictment. Retrieved February 3, 2021.", "source_name": "Phish Labs Silent Librarian", "url": "https://info.phishlabs.com/blog/silent-librarian-more-to-the-story-of-the-iranian-mabna-institute-indictment"}, {"description": "Proofpoint Threat Insight Team. (2019, September 5). Threat Actor Profile: TA407, the Silent Librarian. Retrieved February 3, 2021.", "source_name": "Proofpoint TA407 September 2019", "url": "https://www.proofpoint.com/us/threat-insight/post/threat-actor-profile-ta407-silent-librarian"}], "id": "relationship--33201f98-6367-4f36-a581-98fd4d1203fa", "modified": "2026-07-31T18:48:09.113Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--90784c1e-4aba-40eb-9adf-7556235e6384", "spec_version": "2.1", "target_ref": "attack-pattern--16cdd21f-da65-4e4f-bc04-dd7d198c7b26", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity-