VALUES ('doc-09-mitre-attack-p0-11176', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-20T03:06:40.236Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Silent Librarian](https://attack.mitre.org/groups/G0122) has cloned victim organization login pages and staged them for later use in credential harvesting campaigns. [Silent Librarian](https://attack.mitre.org/groups/G0122) has also made use of a variety of URL shorteners for these staged websites.(Citation: Secureworks COBALT DICKENS September 2019)(Citation: Malwarebytes Silent Librarian October 2020)(Citation: Proofpoint TA407 September 2019)", "external_references": [{"description": "Counter Threat Unit Research Team. (2019, September 11). COBALT DICKENS Goes Back to School…Again. Retrieved February 3, 2021.", "source_name": "Secureworks COBALT DICKENS September 2019", "url": "https://www.secureworks.com/blog/cobalt-dickens-goes-back-to-school-again"}, {"description": "Malwarebytes Threat Intelligence Team. (2020, October 14). Silent Librarian APT right on schedule for 20/21 academic year. Retrieved February 3, 2021.", "source_name": "Malwarebytes Silent Librarian October 2020", "url": "https://blog.malwarebytes.com/malwarebytes-news/2020/10/silent-librarian-apt-phishing-attack/"}, {"description": "Proofpoint Threat Insight Team. (2019, September 5). Threat Actor Profile: TA407, the Silent Librarian. Retrieved February 3, 2021.", "source_name": "Proofpoint TA407 September 2019", "url": "https://www.proofpoint.com/us/threat-insight/post/threat-actor-profile-ta407-silent-librarian"}], "id": "relationship--9038cd4b-182b-469f-ac45-83dedf5110c9", "modified": "2026-07-31T18:48:09.266Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--90784c1e-4aba-40eb-9adf-7556235e6384", "spec_version": "2.1", "target_ref": "attack-pattern--84ae8255-b4f4-4237-b5c5-e