VALUES ('doc-09-mitre-attack-p0-11188', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-16T18:08:17.485Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Medusa Group](https://attack.mitre.org/groups/G1051) has utilized a file hosting service called filemail[.]com to host a zip file that contained a RMM service such as ConnectWise.(Citation: Palo Alto Unit 42 Medusa Group Medusa Ransomware January 2024)", "external_references": [{"description": "Anthony Galiette, Doel Santos. (2024, January 11). Medusa Ransomware Turning Your Files into Stone. Retrieved October 15, 2025.", "source_name": "Palo Alto Unit 42 Medusa Group Medusa Ransomware January 2024", "url": "https://unit42.paloaltonetworks.com/medusa-ransomware-escalation-new-leak-site/"}], "id": "relationship--1a03f0c5-d8d3-4f5d-9808-9faad0061c14", "modified": "2026-07-31T18:48:10.054Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--918da025-04bd-48af-b6c4-f3e4d1b915eb", "spec_version": "2.1", "target_ref": "attack-pattern--506f6f49-7045-4156-9007-7474cb44ad6d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11188', 0, 95, '09-mitre-attack', 'retrieved', 'E7245DCADE1AED566BAE2CC2963A31B376EFF55DA7E906D1E28250B088AAC75E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
