VALUES ('doc-09-mitre-attack-p0-11191', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-16T17:45:39.477Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Medusa Group](https://attack.mitre.org/groups/G1051) has modified Registry keys to elevate privileges, maintain persistence and allow remote access.(Citation: CISA Medusa Group Medusa Ransomware March 2025)", "external_references": [{"description": "Cybersecurity and Infrastructure Security Agency. (2025, March 12). AA25-071A #StopRansomware: Medusa Ransomware. Retrieved October 15, 2025.", "source_name": "CISA Medusa Group Medusa Ransomware March 2025", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa25-071a"}], "id": "relationship--22af9ec6-fb67-4007-85f8-70a3be7f209f", "modified": "2026-07-31T18:48:10.115Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--918da025-04bd-48af-b6c4-f3e4d1b915eb", "spec_version": "2.1", "target_ref": "attack-pattern--57340c81-c025-4189-8fa0-fc7ede51bae4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11191', 0, 79, '09-mitre-attack', 'retrieved', '0532B5C94634441C2D2C23BDE55BFF03EA91588D2CE9FFA45C5AC246EB9798CC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
