VALUES ('doc-09-mitre-attack-p0-11220', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-15T19:52:33.475Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Medusa Group](https://attack.mitre.org/groups/G1051) has leveraged PowerShell for execution and defense evasion.(Citation: Check Point Medusa Ransomware April 2025)(Citation: CISA Medusa Group Medusa Ransomware March 2025)(Citation: Intel471 Medusa Ransomware May 2025) [Medusa Group](https://attack.mitre.org/groups/G1051) has also utilized PowerShell to execute a bitsadmin transfer from file hosting site.(Citation: Palo Alto Unit 42 Medusa Group Medusa Ransomware January 2024)", "external_references": [{"description": "Anthony Galiette, Doel Santos. (2024, January 11). Medusa Ransomware Turning Your Files into Stone. Retrieved October 15, 2025.", "source_name": "Palo Alto Unit 42 Medusa Group Medusa Ransomware January 2024", "url": "https://unit42.paloaltonetworks.com/medusa-ransomware-escalation-new-leak-site/"}, {"description": "Check Point. (2025, April 16). The 2025 Ransomware Surge: Context for Medusa’s Rise. Retrieved October 15, 2025.", "source_name": "Check Point Medusa Ransomware April 2025", "url": "https://www.checkpoint.com/cyber-hub/threat-prevention/ransomware/medusa-ransomware-group/"}, {"description": "Cybersecurity and Infrastructure Security Agency. (2025, March 12). AA25-071A #StopRansomware: Medusa Ransomware. Retrieved October 15, 2025.", "source_name": "CISA Medusa Group Medusa Ransomware March 2025", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa25-071a"}, {"description": "Intel471. (2025, May 14). Threat hunting case study: Medusa ransomware. Retrieved October 15, 2025.", "source_name": "Intel471 Medusa Ransomware May 2025", "url": "https://www.intel471.com/blog/threat-hunting-case-study-medusa-ransomware"}], "id": "relationship--98e2f79a-e394-4d26-a82e-a15c235d28dd", "modified": "2026-07-31T18:48:10.828Z", "object