VALUES ('doc-09-mitre-attack-p0-11236', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-16T14:59:50.697Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Medusa Group](https://attack.mitre.org/groups/G1051) has terminated antivirus services utilizing the gaze.exe executable and utilizing `psexec.exe`.(Citation: Palo Alto Unit 42 Medusa Group Medusa Ransomware January 2024)(Citation: CISA Medusa Group Medusa Ransomware March 2025)(Citation: Broadcom Medusa Ransomware Medusa Group March 2025) [Medusa Group](https://attack.mitre.org/groups/G1051) has also leveraged I/O control codes (IOCTLs) for terminating and deleting processes of identified security tools.(Citation: Palo Alto Unit 42 Medusa Group Medusa Ransomware January 2024)", "external_references": [{"description": "Anthony Galiette, Doel Santos. (2024, January 11). Medusa Ransomware Turning Your Files into Stone. Retrieved October 15, 2025.", "source_name": "Palo Alto Unit 42 Medusa Group Medusa Ransomware January 2024", "url": "https://unit42.paloaltonetworks.com/medusa-ransomware-escalation-new-leak-site/"}, {"description": "Cybersecurity and Infrastructure Security Agency. (2025, March 12). AA25-071A #StopRansomware: Medusa Ransomware. Retrieved October 15, 2025.", "source_name": "CISA Medusa Group Medusa Ransomware March 2025", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa25-071a"}, {"description": "Threat Hunter Team Symantec and Carbon Black. (2025, March 6). Medusa Ransomware Activity Continues to Increase. Retrieved October 15, 2025.", "source_name": "Broadcom Medusa Ransomware Medusa Group March 2025", "url": "https://www.security.com/threat-intelligence/medusa-ransomware-attacks"}], "id": "relationship--e9027e50-c7dc-4bba-b19b-cd402c00b99c", "modified": "2026-07-31T18:48:11.126Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--918da025-04bd-48af-b6c4-f3e4d1b915eb", "spec_version": "2.1", "target_ref": "attack-pattern--bbde9781-60aa-4b8a-a911-895b0c1b3872", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11236', 0, 185, '09-mitre-attack', 'retrieved', 'D74A722DBE9A39873F81A5E62F39CE563467BBD42533EA1B2FA85D232201B971', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
