VALUES ('doc-09-mitre-attack-p0-11237', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-16T17:03:24.544Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Medusa Group](https://attack.mitre.org/groups/G1051) has the capability to use living off the land (LOTL) binaries to perform network enumeration.(Citation: CISA Medusa Group Medusa Ransomware March 2025) [Medusa Group](https://attack.mitre.org/groups/G1051) has also utilized the publicly available scanning tool SoftPerfect Network Scanner (`netscan.exe`) to discover device hostnames and network services.(Citation: Broadcom Medusa Ransomware Medusa Group March 2025)", "external_references": [{"description": "Cybersecurity and Infrastructure Security Agency. (2025, March 12). AA25-071A #StopRansomware: Medusa Ransomware. Retrieved October 15, 2025.", "source_name": "CISA Medusa Group Medusa Ransomware March 2025", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa25-071a"}, {"description": "Threat Hunter Team Symantec and Carbon Black. (2025, March 6). Medusa Ransomware Activity Continues to Increase. Retrieved October 15, 2025.", "source_name": "Broadcom Medusa Ransomware Medusa Group March 2025", "url": "https://www.security.com/threat-intelligence/medusa-ransomware-attacks"}], "id": "relationship--ebf193e2-d75e-4204-80cd-a9791d7d3c18", "modified": "2026-07-31T18:48:11.151Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--918da025-04bd-48af-b6c4-f3e4d1b915eb", "spec_version": "2.1", "target_ref": "attack-pattern--e3a12395-188d-4051-9a16-ea8e14d07b88", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11237', 0, 140, '09-mitre-attack', 'retrieved', '7AFC6680BDE7AC5ABCDEDA527B849F4676