VALUES ('doc-09-mitre-attack-p0-11286', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BRONZE BUTLER](https://attack.mitre.org/groups/G0060) has used RC4 encryption (for Datper malware) and AES (for xxmm malware) to obfuscate HTTP traffic. [BRONZE BUTLER](https://attack.mitre.org/groups/G0060) has also used a tool called RarStar that encodes data with a custom XOR algorithm when posting it to a C2 server.(Citation: Secureworks BRONZE BUTLER Oct 2017)", "external_references": [{"description": "Counter Threat Unit Research Team. (2017, October 12). BRONZE BUTLER Targets Japanese Enterprises. Retrieved January 4, 2018.", "source_name": "Secureworks BRONZE BUTLER Oct 2017", "url": "https://www.secureworks.com/research/bronze-butler-targets-japanese-businesses"}], "id": "relationship--ec4d07a2-8c8b-4df8-bb9e-b8c3e23d8dc5", "modified": "2026-07-31T18:48:11.034Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--93f52415-0fe4-4d3d-896c-fc9b8e88ab90", "spec_version": "2.1", "target_ref": "attack-pattern--24bfaeba-cb0d-4525-b3dc-507c77ecec41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11286', 0, 103, '09-mitre-attack', 'retrieved', 'F52030F266411DB054C6DA71AFF93469254927ADF0228913B9AD92CA6BB39FC7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
