VALUES ('doc-09-mitre-attack-p0-11375', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-05T20:52:47.420Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Darkhotel](https://attack.mitre.org/groups/G0012) malware has employed just-in-time decryption of strings to evade sandbox detection.(Citation: Lastline DarkHotel Just In Time Decryption Nov 2015)", "external_references": [{"description": "Arunpreet Singh, Clemens Kolbitsch. (2015, November 5). Defeating Darkhotel Just-In-Time Decryption. Retrieved April 15, 2021.", "source_name": "Lastline DarkHotel Just In Time Decryption Nov 2015", "url": "https://www.lastline.com/labsblog/defeating-darkhotel-just-in-time-decryption/"}], "id": "relationship--7cc93842-6c19-4d5c-8e9b-81dfa58e859e", "modified": "2026-07-31T18:48:11.960Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--9e729a7e-0dd6-4097-95bf-db8d64911383", "spec_version": "2.1", "target_ref": "attack-pattern--82caa33e-d11a-433a-94ea-9b5a5fbef81d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11375', 0, 77, '09-mitre-attack', 'retrieved', 'D0C178DC39FEC8567425D2DCABC83B275697CBEC81D8E2546E4C25DB21A3CABF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
