VALUES ('doc-09-mitre-attack-p0-11376', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-05T20:52:47.408Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Darkhotel](https://attack.mitre.org/groups/G0012) malware has used a series of checks to determine if it''s being analyzed; checks include the length of executable names, if a filename ends with .Md5.exe , and if the program is executed from the root of the C:\\ drive, as well as checks for sandbox-related libraries.(Citation: Lastline DarkHotel Just In Time Decryption Nov 2015)(Citation: Microsoft DUBNIUM June 2016)", "external_references": [{"description": "Arunpreet Singh, Clemens Kolbitsch. (2015, November 5). Defeating Darkhotel Just-In-Time Decryption. Retrieved April 15, 2021.", "source_name": "Lastline DarkHotel Just In Time Decryption Nov 2015", "url": "https://www.lastline.com/labsblog/defeating-darkhotel-just-in-time-decryption/"}, {"description": "Microsoft. (2016, June 9). Reverse-engineering DUBNIUM. Retrieved March 31, 2021.", "source_name": "Microsoft DUBNIUM June 2016", "url": "https://www.microsoft.com/security/blog/2016/06/09/reverse-engineering-dubnium-2/"}], "id": "relationship--8395d178-d5e8-494f-8612-3c2542b2f8c9", "modified": "2026-07-31T18:48:11.971Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--9e729a7e-0dd6-4097-95bf-db8d64911383", "spec_version": "2.1", "target_ref": "attack-pattern--29be378d-262d-4e99-b00d-852d573628e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11376', 0, 135, '09-mitre-attack', 'retrieved', '8D72F08E92FA2E2F5DD57460A327C467933CE9BBAA7465F0070C9A0B3B8D7CAC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1",