VALUES ('doc-09-mitre-attack-p0-11377', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-05T20:52:47.428Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Darkhotel](https://attack.mitre.org/groups/G0012) malware can obtain system time from a compromised host.(Citation: Lastline DarkHotel Just In Time Decryption Nov 2015)", "external_references": [{"description": "Arunpreet Singh, Clemens Kolbitsch. (2015, November 5). Defeating Darkhotel Just-In-Time Decryption. Retrieved April 15, 2021.", "source_name": "Lastline DarkHotel Just In Time Decryption Nov 2015", "url": "https://www.lastline.com/labsblog/defeating-darkhotel-just-in-time-decryption/"}], "id": "relationship--9158696f-fdc6-4869-a395-5d94c7c13d26", "modified": "2026-07-31T18:48:11.986Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--9e729a7e-0dd6-4097-95bf-db8d64911383", "spec_version": "2.1", "target_ref": "attack-pattern--f3c544dc-673c-4ef3-accb-53229f1ae077", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11377', 0, 75, '09-mitre-attack', 'retrieved', '51C7AECAF40C3F8B9865492FC5219EE9840337762E8709D95EC2A8CA2A3FD8C7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
