VALUES ('doc-09-mitre-attack-p0-11378', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.047Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Darkhotel](https://attack.mitre.org/groups/G0012) has used code-signing certificates on its malware that are either forged due to weak keys or stolen. [Darkhotel](https://attack.mitre.org/groups/G0012) has also stolen certificates and signed backdoors and downloaders with them.(Citation: Kaspersky Darkhotel)(Citation: Securelist Darkhotel Aug 2015)", "external_references": [{"description": "Kaspersky Lab''s Global Research and Analysis Team. (2014, November). The Darkhotel APT A Story of Unusual Hospitality. Retrieved November 12, 2014.", "source_name": "Kaspersky Darkhotel", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2018/03/08070903/darkhotel_kl_07.11.pdf"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2015, August 10). Darkhotel''s attacks in 2015. Retrieved November 2, 2018.", "source_name": "Securelist Darkhotel Aug 2015", "url": "https://securelist.com/darkhotels-attacks-in-2015/71713/"}], "id": "relationship--b69424ec-3af6-44aa-842a-81fba219b9f4", "modified": "2026-07-31T18:48:11.999Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--9e729a7e-0dd6-4097-95bf-db8d64911383", "spec_version": "2.1", "target_ref": "attack-pattern--32901740-b42c-4fdd-bc02-345b5dc57082", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11378', 0, 119, '09-mitre-attack', 'retrieved', 'D325E48129DF096D4BAC43D5175D9625AAA6F6EA0B8C58F749F0634E2D30644C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRU